insert into public.workout_sessions (
  member_id,
  workout_date,
  session_no,
  exercise_type,
  duration_minutes,
  start_image_path,
  end_image_path,
  notes,
  created_by,
  created_at
)
select
  m.id,
  sr.workout_date::date,
  sr.session_no,
  sr.exercise_type,
  sr.duration_minutes,
  sr.start_image_path,
  sr.end_image_path,
  sr.notes,
  'kakao_import',
  sr.created_at::timestamptz
from source_rows sr
join public.members m on m.name = sr.member_name
where not exists (
  select 1
  from public.workout_sessions ws
  where ws.member_id = m.id
    and ws.workout_date = sr.workout_date::date
    and ws.session_no = sr.session_no
);

commit;
